-- Registered workload assertions keep the system Principal tenant-local; only V4 carries a separately admitted operation company.
CREATE OR REPLACE FUNCTION trust.register_gateway_scope_grant(p_assertion text, p_audience text, p_jti uuid, p_principal_id uuid, p_tenant_id uuid, p_legal_entity_id uuid, p_expires_at timestamptz) RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$ DECLARE v_now timestamptz := pg_catalog.clock_timestamp(); v_encoded text; v_claims jsonb; v_claims_match boolean := false; BEGIN IF p_assertion IS NULL OR pg_catalog.length(p_assertion) > 8192 OR p_assertion !~ '^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$' OR p_audience IS NULL OR p_jti IS NULL OR p_principal_id IS NULL OR p_tenant_id IS NULL OR p_expires_at IS NULL OR p_expires_at <= v_now OR p_expires_at > v_now + interval '330 seconds' THEN RAISE EXCEPTION 'gateway scope grant is invalid' USING ERRCODE = '22023'; END IF; IF NOT EXISTS (SELECT 1 FROM trust.gateway_audience_roles AS a WHERE a.audience = p_audience) THEN RAISE EXCEPTION 'gateway audience is not enrolled for scope grants' USING ERRCODE = '22023'; END IF; v_encoded := pg_catalog.translate(pg_catalog.split_part(p_assertion, '.', 2), '-_', '+/'); BEGIN v_claims := pg_catalog.convert_from(pg_catalog.decode(v_encoded || pg_catalog.repeat('=', (4 - pg_catalog.length(v_encoded) % 4) % 4), 'base64'), 'UTF8')::jsonb; v_claims_match := pg_catalog.jsonb_typeof(v_claims) = 'object' AND pg_catalog.jsonb_typeof(v_claims -> 'principal') = 'object' AND pg_catalog.jsonb_typeof(v_claims -> 'aud') = 'string' AND pg_catalog.jsonb_typeof(v_claims -> 'jti') = 'string' AND pg_catalog.jsonb_typeof(v_claims -> 'sub') = 'string' AND pg_catalog.jsonb_typeof(v_claims -> 'exp') = 'number' AND pg_catalog.jsonb_typeof(v_claims #> '{principal,principalId}') = 'string' AND pg_catalog.jsonb_typeof(v_claims #> '{principal,tenantId}') = 'string' AND COALESCE(pg_catalog.jsonb_typeof(v_claims #> '{principal,legalEntityId}'), 'string') = 'string' AND (v_claims ->> 'aud') = p_audience AND (v_claims ->> 'jti')::uuid = p_jti AND (v_claims ->> 'sub')::uuid = p_principal_id AND (v_claims #>> '{principal,principalId}')::uuid = p_principal_id AND (v_claims #>> '{principal,tenantId}')::uuid = p_tenant_id AND (CASE WHEN v_claims ->> 'ver' = '4' AND v_claims #>> '{principal,authMethod}' = 'system' AND v_claims #> '{principal,legalEntityId}' IS NULL THEN v_claims #>> '{workload,legalEntityId}' ELSE v_claims #>> '{principal,legalEntityId}' END)::uuid IS NOT DISTINCT FROM p_legal_entity_id AND (v_claims ->> 'exp')::numeric = EXTRACT(EPOCH FROM p_expires_at); EXCEPTION WHEN data_exception THEN v_claims_match := false; END; IF v_claims_match IS NOT TRUE THEN RAISE EXCEPTION 'gateway scope grant arguments do not match the assertion claims' USING ERRCODE = '22023'; END IF; IF NOT EXISTS (SELECT 1 FROM core.principals AS p WHERE p.principal_id = p_principal_id AND p.tenant_id = p_tenant_id AND p.status = 'active') THEN RAISE EXCEPTION 'gateway scope principal is not an active principal of the tenant' USING ERRCODE = '22023'; END IF; IF p_legal_entity_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM core.legal_entities AS l WHERE l.legal_entity_id = p_legal_entity_id AND l.tenant_id = p_tenant_id) THEN RAISE EXCEPTION 'gateway scope legal entity does not belong to the tenant' USING ERRCODE = '22023'; END IF; DELETE FROM trust.gateway_scope_grants AS g WHERE g.assertion_digest IN (SELECT e.assertion_digest FROM trust.gateway_scope_grants AS e WHERE e.expires_at < v_now - interval '60 seconds' ORDER BY e.expires_at LIMIT 500 FOR UPDATE SKIP LOCKED); INSERT INTO trust.gateway_scope_grants (assertion_digest, audience, jti, principal_id, tenant_id, legal_entity_id, expires_at, registered_at, registered_by) VALUES (pg_catalog.sha256(pg_catalog.convert_to(p_assertion, 'UTF8')), p_audience, p_jti, p_principal_id, p_tenant_id, p_legal_entity_id, LEAST(p_expires_at, v_now + interval '300 seconds'), v_now, SESSION_USER); END $$;
